"""World generation exact: a normal world (fixed seed), an area generated by forceloading it, its blocks and block
entities hashed over the whole height; optimisations off vs on (the defaults). The flat test world of the other tools
never runs the noise, surface, aquifer and ore code.
    python tools/genhash.py [--x 2000 --z 2000 --chunks 8] [--flags "..."]"""
import argparse
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from server import Server, RUN  # noqa: E402

ap = argparse.ArgumentParser()
ap.add_argument('--x', type=int, default=2000)
ap.add_argument('--z', type=int, default=2000)
ap.add_argument('--chunks', type=int, default=8)
ap.add_argument('--seed', default='20261104')
ap.add_argument('--flags', default='')
ap.add_argument('--offoff', action='store_true', help='both runs without the optimisations: is generation deterministic here')
a = ap.parse_args()
x1, z1 = a.x, a.z
x2, z2 = x1 + a.chunks * 16 - 1, z1 + a.chunks * 16 - 1
props = {'level-type': 'minecraft\\:normal', 'generator-settings': '{}', 'level-seed': a.seed}
out = {}
for mode in ('off', 'on'):
    jvm = ['-Dsleep.hashClientNbt=true'] + (['-Dlab.opt.defaults=true'] + a.flags.split() if mode == 'on' and not a.offoff else [])
    t0 = time.time()
    with Server(jvm, props, os.path.join(RUN, 'genhash-%s.log' % mode)) as s:
        s.wait_for(r'Done \(', 600)
        s.cmd('tick freeze')   # generation only: no fluid / random ticks changing the area while it loads
        s.cmd('forceload add %d %d %d %d' % (x1, z1, x2, z2))
        for x, z in ((x1, z1), (x2, z2), (x1, z2), (x2, z1)):   # all four corners loaded (full chunks)
            while s.ask('execute if loaded %d 0 %d' % (x, z), r'Test (passed|failed)', 60).group(1) != 'passed':
                time.sleep(1)
        time.sleep(3)
        h = s.ask('sleep hash %d -64 %d %d 319 %d' % (x1, z1, x2, z2), r'region hash (\w+) \(block entities (\d+)', 600)
        out[mode] = (h.group(1), int(h.group(2)))
        errs = s.errors()
    print('%-3s %s  (block entities %d)%s  %.0f s' % (mode, out[mode][0], out[mode][1], '  %d errors in the log' % len(errs) if errs else '', time.time() - t0), flush=True)
print('EXACT' if out['off'] == out['on'] else 'DIFFERENT')
